  function prep(ctx, o) { o = o || {}; const sc = ctx.scene; if (!GT.cnroad && !o.room) { const g = new T.Mesh(new T.PlaneGeometry(400, 400), GT.mat('asphalt_worn')); g.rotation.x = -HP; g.position.set(40, -.02, 90); g.receiveShadow = true; const uv = g.geometry.attributes.uv; for (let i = 0; i < uv.count; i++) uv.setXY(i, uv.getX(i) * 400, uv.getY(i) * 400); sc.add(g); }
    if (GT.cnroad && GT.cnroad.build && !o.room && Q.get('road') !== '0') { try { GT.cnroad.build(sc); S.roadUp = GT.cnroad.update; } catch (e) { /* optional */ } }
    build(sc); if (o.room) { if (Q.get('fig') === '1' && GT.hero) { try { const f = S.standIn = GT.hero.make('kai', { outfit: 'rider' }); f.group.position.set(76.4, 0, 69.9); f.group.rotation.y = HP + .4; sc.add(f.group); f.update(.016, { state: 'idle', speed: 0, t: 1 }); } catch (e) { /* optional */ } } setInside(true, null); if (Q.get('ch')) setChannel(+Q.get('ch')); if (Q.get('charge')) S.phone = 1; }
    if (Q.get('dbg')) setTimeout(() => { const e = document.getElementById('err'); if (e) e.textContent += JSON.stringify(API.stats) + '\n'; }, 50);
    let pre = +(Q.get('at') || 3); while (pre > 0) { update(.05); pre -= .05; } return { update(dt) { update(dt); if (S.roadUp) { try { S.roadUp.call(GT.cnroad, dt); } catch (e) { /* optional */ } } } }; }
  const SC = (name, cam, look, hours, o) => { GT.showcase[name] = ctx => Object.assign(prep(ctx, o), { cam, look, hours }); };
  SC('hotpot', [28.5, 1.8, 87.2], [36.8, 5.2, 102], 21); SC('hotpot_inside', [35.5, 1.7, 104.7], [31.3, .95, 108.6], 19.5); SC('hotpot_table', [31.14, 1.3, 106.08], [32.02, .8, 106.92], 19.5);
